// AscendC MoeComputeExpertTokens kernel
// Multi-core histogram (bincount) + merge + prefix sum (cumsum)
// Data type: int32 only

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Helper: load tile from GM to UB, return the tile length (may be tail-short)
// ---------------------------------------------------------------------------
template <typename T>
__aicore__ inline void LoadGmToUb(
    LocalTensor<T> &dst,
    const GlobalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const GlobalTensor<T> &dst,
    const LocalTensor<T> &src,
    int32_t count)
{
    if (count <= 0) { return; }
    DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
    DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// MoeComputeExpertTokens Kernel
// =========================================================================

class KernelMoeComputeExpertTokens {
public:
    __aicore__ inline void Init(
        GM_ADDR sorted_expert,
        GM_ADDR expert_tokens,
        GM_ADDR workspace,
        int64_t N,
        int64_t num_expert,
        int64_t usedCoreNum,
        int64_t N_per_core,
        int64_t tile_size)
    {
        this->totalN = N;
        this->numExpert = num_expert;
        this->usedCoreNum = usedCoreNum;
        this->NPerCore = N_per_core;
        this->tileSize = tile_size;

        // Compute this core's element range
        coreIdx = static_cast<int64_t>(GetBlockIdx());
        elemStart = coreIdx * NPerCore;
        elemEnd = (elemStart + NPerCore > totalN) ? totalN : (elemStart + NPerCore);
        curElems = elemEnd - elemStart;

        // Set up global tensors
        sortedExpertGm.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(sorted_expert),
            static_cast<uint64_t>(totalN));
        expertTokensGm.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(expert_tokens),
            static_cast<uint64_t>(numExpert));
        workspaceGm.SetGlobalBuffer(
            reinterpret_cast<__gm__ int32_t *>(workspace),
            static_cast<uint64_t>(usedCoreNum * numExpert));

        // Allocate UB buffers
        pipe.InitBuffer(inQueue, BUFFER_NUM, static_cast<uint32_t>(tileSize * sizeof(int32_t)));
        pipe.InitBuffer(histBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));
    }

    __aicore__ inline void Process()
    {
        // Initialize histogram to 0
        histLocal = histBuf.Get<int32_t>();
        Duplicate(histLocal, (int32_t)0, static_cast<int32_t>(numExpert));

        // === Phase 1: Per-core histogram ===
        numTiles = (curElems + tileSize - 1) / tileSize;

        for (int64_t tileIdx = 0; tileIdx < numTiles; ++tileIdx) {
            int64_t tileStart = tileIdx * tileSize;
            int64_t tileEnd = (tileStart + tileSize > curElems) ? curElems : (tileStart + tileSize);
            int32_t curTileLen = static_cast<int32_t>(tileEnd - tileStart);

            // CopyIn: load input tile from GM to UB
            inLocal = inQueue.AllocTensor<int32_t>();
            GlobalTensor<int32_t> inputGmSlice = sortedExpertGm[elemStart + tileStart];
            LoadGmToUb(inLocal, inputGmSlice, curTileLen);
            inQueue.EnQue(inLocal);

            // Compute: process tile, update histogram
            inLocal = inQueue.DeQue<int32_t>();

            // Process each element in the tile; the outer parallelism is at the
            // core level (20 cores), so a scalar tile loop is efficient.
            for (int32_t i = 0; i < curTileLen; ++i) {
                int32_t expertIdx = inLocal(i);
                if (expertIdx >= 0 && expertIdx < static_cast<int32_t>(numExpert)) {
                    histLocal(expertIdx) = histLocal(expertIdx) + (int32_t)1;
                }
            }
            inQueue.FreeTensor(inLocal);
        }

        // Write local histogram to workspace
        int64_t wsOffset = coreIdx * numExpert;
        GlobalTensor<int32_t> wsSlice = workspaceGm[wsOffset];
        StoreUbToGm(wsSlice, histLocal, static_cast<int32_t>(numExpert));
        PipeBarrier<PIPE_ALL>();

        // === Phase 2: Core 0 merges ===
        // SyncAll: wait for all cores to write their histograms to workspace
        SyncAll();

        if (coreIdx == 0) {
            // Allocate merge buffer
            pipe.InitBuffer(mergeBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));
            pipe.InitBuffer(readBuf, static_cast<uint32_t>(numExpert * sizeof(int32_t)));

            mergeLocal = mergeBuf.Get<int32_t>();
            readLocal = readBuf.Get<int32_t>();

            // Initialize merge to zero
            Duplicate(mergeLocal, (int32_t)0, static_cast<int32_t>(numExpert));

            // Read and sum all partial histograms from workspace
            for (int64_t c = 0; c < usedCoreNum; ++c) {
                int64_t wsCoreOffset = c * numExpert;
                GlobalTensor<int32_t> wsCoreSlice = workspaceGm[wsCoreOffset];
                LoadGmToUb(readLocal, wsCoreSlice, static_cast<int32_t>(numExpert));
                PipeBarrier<PIPE_MTE2>();
                PipeBarrier<PIPE_V>();
                Add(mergeLocal, mergeLocal, readLocal, static_cast<int32_t>(numExpert));
                PipeBarrier<PIPE_V>();
            }

            // Prefix sum (cumsum) in-place on mergeLocal
            // This is inherently sequential: output[i] = output[i-1] + mergeLocal[i]
            PipeBarrier<PIPE_ALL>();
            for (int32_t i = 1; i < static_cast<int32_t>(numExpert); ++i) {
                mergeLocal(i) = mergeLocal(i - 1) + mergeLocal(i);
            }
            PipeBarrier<PIPE_ALL>();

            // Write output to GM
            StoreUbToGm(expertTokensGm, mergeLocal, static_cast<int32_t>(numExpert));
            PipeBarrier<PIPE_ALL>();
        }
    }

private:
    AscendC::TPipe pipe;

    // Global tensors
    GlobalTensor<int32_t> sortedExpertGm;
    GlobalTensor<int32_t> expertTokensGm;
    GlobalTensor<int32_t> workspaceGm;

    // UB buffers
    TQue<QuePosition::VECIN, BUFFER_NUM> inQueue;
    TBuf<TPosition::VECCALC> histBuf;
    TBuf<TPosition::VECCALC> mergeBuf;
    TBuf<TPosition::VECCALC> readBuf;

    // Local tensors
    LocalTensor<int32_t> inLocal;
    LocalTensor<int32_t> histLocal;
    LocalTensor<int32_t> mergeLocal;
    LocalTensor<int32_t> readLocal;

    // Parameters
    int64_t totalN = 0;
    int64_t numExpert = 0;
    int64_t usedCoreNum = 0;
    int64_t NPerCore = 0;
    int64_t tileSize = 0;
    int64_t coreIdx = 0;
    int64_t elemStart = 0;
    int64_t elemEnd = 0;
    int64_t curElems = 0;
    int64_t numTiles = 0;
};

// =========================================================================
// Kernel entry point
// =========================================================================

extern "C" __global__ __aicore__ void moe_compute_expert_tokens(
    GM_ADDR sorted_expert,
    GM_ADDR expert_tokens,
    GM_ADDR workspace,
    int64_t N,
    int64_t num_expert,
    int64_t usedCoreNum,
    int64_t N_per_core,
    int64_t tile_size)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) {
        return;
    }

    KernelMoeComputeExpertTokens kernel;
    kernel.Init(sorted_expert, expert_tokens, workspace,
                N, num_expert, usedCoreNum, N_per_core, tile_size);
    kernel.Process();
}
