// MoeComputeExpertTokens op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_moe_compute_expert_tokens.h"

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

constexpr int32_t NUM_PHYSICAL_CORES = 20;
constexpr int32_t DEFAULT_TILE_SIZE = 256;
constexpr int32_t CACHE_LINE_ALIGN = 512;  // 512 bytes

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor moe_compute_expert_tokens(
    const at::Tensor &sorted_expert_for_source_row,
    int64_t num_expert)
{
    // Input validation
    TORCH_CHECK(sorted_expert_for_source_row.dim() == 1,
                "sorted_expert_for_source_row must be 1D");
    TORCH_CHECK(sorted_expert_for_source_row.scalar_type() == at::kInt,
                "sorted_expert_for_source_row must be int32");
    TORCH_CHECK(sorted_expert_for_source_row.is_contiguous(),
                "sorted_expert_for_source_row must be contiguous");
    TORCH_CHECK(num_expert > 0,
                "num_expert must be > 0");

    int64_t N = sorted_expert_for_source_row.size(0);

    // Tiling calculation
    auto ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) {
        coreNum = NUM_PHYSICAL_CORES;
    }
    // Use the minimum of available cores and what we actually need
    int64_t usedCoreNum = (N + DEFAULT_TILE_SIZE - 1) / DEFAULT_TILE_SIZE;
    usedCoreNum = std::max<int64_t>(1, std::min<int64_t>(usedCoreNum, coreNum));
    if (usedCoreNum < 1) { usedCoreNum = 1; }

    int64_t NPerCore = (N + usedCoreNum - 1) / usedCoreNum;

    // Tile size based on UB
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    // UB budget: we need tileSize * sizeof(int32) for input (double buffer x1),
    // plus num_expert * sizeof(int32) for histogram.
    // Safe: use ~80% of UB capacity
    int64_t maxTileFromUb = static_cast<int64_t>(
        (ubSize * 8 / 10 - static_cast<uint64_t>(num_expert) * sizeof(int32_t))
        / sizeof(int32_t));
    int64_t tileSize = std::min<int64_t>(DEFAULT_TILE_SIZE,
        std::max<int64_t>(32, maxTileFromUb));
    // Align to 32 elements for DataCopyPad compatibility
    tileSize = (tileSize / 32) * 32;
    if (tileSize < 32) { tileSize = 32; }

    // Workspace: [usedCoreNum, num_expert] int32
    int64_t workspaceElems = usedCoreNum * num_expert;
    at::Tensor workspace = at::empty(
        {workspaceElems},
        sorted_expert_for_source_row.options().dtype(at::kInt));

    // Output
    at::Tensor expert_tokens = at::empty(
        {num_expert},
        sorted_expert_for_source_row.options().dtype(at::kInt));

    // EXEC_KERNEL_CMD requires all parameters as left-values
    int64_t totalN = N;
    int64_t numExpert = num_expert;
    int64_t usedCoreNumLv = usedCoreNum;
    int64_t NPerCoreLv = NPerCore;
    int64_t tileSizeLv = tileSize;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(moe_compute_expert_tokens, blockDim,
                    sorted_expert_for_source_row, expert_tokens, workspace,
                    totalN, numExpert, usedCoreNumLv, NPerCoreLv, tileSizeLv);

    return expert_tokens;
}

}  // namespace ascend_kernel
