    GM_ADDR sorted_expert,
    GM_ADDR expert_tokens,
    int64_t N,
    int64_t num_expert,
    int64_t tile_size)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) { return; }

    KernelMoeComputeExpertTokens kernel;
    kernel.Init(sorted_expert, expert_tokens,
                N, num_expert, tile_size);
    kernel.Process();
}
